<!doctype html>
<html lang="id" data-theme="light">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRM Camp Resident MUTU</title><style>
:root{font-family:system-ui;color:#172033;background:#f5f7fb}body{margin:0}.wrap{max-width:1100px;margin:auto;padding:2rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:1rem}.card{background:white;border-radius:14px;padding:1.25rem;box-shadow:0 4px 18px #17203312}.muted{color:#64748b}button{border:0;border-radius:8px;padding:.6rem 1rem;cursor:pointer}@media(prefers-color-scheme:dark){:root{color:#e5e7eb;background:#111827}.card{background:#1f2937}} </style></head>
<body><main class="wrap"><header><h1>CRM Camp Resident MUTU</h1><p class="muted">Dashboard operasional harian</p></header><section id="stats" class="grid"><div class="card">Memuat data…</div></section><section class="card" style="margin-top:1rem"><h2>Booking terbaru</h2><div id="bookings">Silakan masuk untuk melihat data.</div></section></main><script>
async function load(){const r=await fetch('/api/v1/dashboard',{headers:{Accept:'application/json'}});if(!r.ok)return;const d=await r.json();document.querySelector('#stats').innerHTML=[['Booking hari ini',d.bookings_today],['Tamu aktif',d.active_guests],['Kamar tersedia',d.available_rooms],['Menunggu konfirmasi',d.pending_bookings]].map(x=>`<div class="card"><div class="muted">${x[0]}</div><h2>${x[1]}</h2></div>`).join('');document.querySelector('#bookings').innerHTML=d.recent_bookings.map(b=>`<p><b>${b.booking_code}</b> — ${b.guest.name} (${b.status})</p>`).join('')||'Belum ada booking.'}load();
</script></body></html>
